        var max = Math.max((document.documentElement.scrollHeight || 0) - window.innerHeight, 1);
        var p = Math.max(0, Math.min(1, y / max));
        if (progress) progress.style.transform = "scaleX(" + p + ")";
        header.classList.toggle("p7-header--dense", y > 64);

        var line = y + 120;
